(() => {
'use strict';
const D=window.ATLAS_DATA, $=s=>document.querySelector(s), main=$('#main'), dialog=$('#record-dialog');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeURL=s=>/^https?:\/\//i.test(String(s).trim())?String(s).trim():'#';
const external=(url,text,cls='')=>`<a class="${cls}" href="${esc(safeURL(url))}" target="_blank" rel="noopener noreferrer">${esc(text)}</a>`;
const icons={grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',timeline:'<path d="M6 3v18M10 6h10M10 12h7M10 18h10"/><circle cx="6" cy="6" r="1.5"/><circle cx="6" cy="12" r="1.5"/><circle cx="6" cy="18" r="1.5"/>',compare:'<rect x="3" y="5" width="7" height="15" rx="1.5"/><rect x="14" y="5" width="7" height="15" rx="1.5"/><path d="M5 9h3M16 9h3M5 13h3M16 13h3"/>',bulb:'<path d="M9 18h6M9 21h6M8 15c-5-4-2-12 4-12s9 8 4 12l-1 3H9z"/>',book:'<path d="M12 6c-3-2-6-2-9-1v15c3-1 6-1 9 1 3-2 6-2 9-1V5c-3-1-6-1-9 1v15"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7h.01"/>',atom:'<ellipse cx="12" cy="12" rx="10" ry="4"/><ellipse cx="12" cy="12" rx="10" ry="4" transform="rotate(60 12 12)"/><ellipse cx="12" cy="12" rx="10" ry="4" transform="rotate(120 12 12)"/><circle cx="12" cy="12" r="1"/>',flask:'<path d="M9 3h6M10 3v6L4 19a1.4 1.4 0 0 0 1.2 2h13.6a1.4 1.4 0 0 0 1.2-2L14 9V3M8 14h8M9 17h.01M14 18h.01"/>',dna:'<path d="M6 2c0 10 12 10 12 20M18 2C18 12 6 12 6 22M7 5h10M8 8h8M8 16h8M7 19h10"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6zM8 11l3 3 5-6"/>',plane:'<path d="m3 12 7-2 1-7h2l1 7 7 2v2l-7-1-1 6 3 2H8l3-2-1-6-7 1z"/>',cross:'<rect x="3" y="3" width="18" height="18" rx="4"/><path d="M8 12h8M12 8v8"/>',bank:'<path d="m3 8 9-5 9 5H3M5 10v8M10 10v8M14 10v8M19 10v8M3 21h18"/>',medal:'<circle cx="12" cy="14" r="7"/><path d="m7 8-3-5h5l3 4 3-4h5l-3 5M12 10v8M9 12l3-2"/>',leaf:'<path d="M20 3C8 2 2 9 6 16s16 3 14-13ZM4 21 15 10M8 17v-5M8 17h5"/>',box:'<path d="m12 3 9 5v10l-9 4-9-4V8zM3 8l9 5 9-5M12 13v9M7 5l10 5"/>',download:'<path d="M12 3v12m-4-4 4 4 4-4M4 17v4h16v-4"/>',link:'<path d="m10 13 4-4M8 15l-2 2a3 3 0 0 1-4-4l5-5a3 3 0 0 1 4 0m2 3a3 3 0 0 0 4 0l5-5a3 3 0 0 0-4-4l-2 2"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>'};
const icon=name=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.info}</svg>`;
const navs=[['sectors','grid','Explore sectors'],['timeline','timeline','Historical timeline'],['compare','compare','Compare sectors'],['lessons','bulb','Lessons for AI'],['evidence','book','Evidence library'],['methods','info','Sources & methods']];
const stages=['Emergence','Hardening','Detection','Consequence','Survival'];
const stageText={Emergence:'How a concern becomes a proposed boundary, and who builds support for it.',Hardening:'How commitments specify the prohibited activity, scope and conditions for permitted work.',Detection:'Who can obtain evidence, evaluate it and investigate suspected non-compliance.',Consequence:'How a finding connects to prevention, remedies, sanctions and review.',Survival:'How participation, monitoring and technical rules are sustained or revised.'};
const sector=id=>D.sectors.find(s=>s.id===id);
const byId=id=>D.records.find(r=>r.uid===id)||D.records.find(r=>r.id===id);
const byUid=id=>D.records.find(r=>r.uid===id);
let state, previousRoute='', focusBeforeDialog=null, toastTimer;
function readState(){const raw=location.hash.slice(1)||'sectors';const [route,q]=raw.split('?');return {route:navs.some(n=>n[0]===route)||route.startsWith('sector/')?route:'sectors',p:new URLSearchParams(q||'')};}
function url(route,params={}){const p=new URLSearchParams();for(const [k,v]of Object.entries(params))if(v!==''&&v!==null&&v!==undefined)p.set(k,v);return '#'+route+(p.size?'?'+p:'');}
function currentUrl(patch={},remove=[]){const p=new URLSearchParams(state.p);remove.forEach(k=>p.delete(k));for(const[k,v]of Object.entries(patch)){if(v===null||v==='')p.delete(k);else p.set(k,v);}return '#'+state.route+(p.size?'?'+p:'');}
function navigate(patch,remove=[],replace=false){const next=currentUrl(patch,remove);if(replace){history.replaceState(null,'',next);state=readState();}else location.hash=next;}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3500);}
function pills(r){return `<span class="pill type">${esc(r.type||'Not coded')}</span><span class="pill ${r.verified?'checked':'pending'}">${r.verified?'Marked verified':'Not marked verified'}</span>${r.review!=='Clean'?`<span class="pill query">${esc(r.review||'Review not recorded')}</span>`:''}`;}
function recordHref(r){return currentUrl({record:r.uid});}
function refs(ids,{review=false}={}){return `<div class="evidence-links ${review?'with-review':''}">${ids.map(id=>byId(id)).filter(Boolean).map(r=>`<div class="evidence-reference"><a class="evidence-chip" href="${esc(recordHref(r))}" aria-label="Inspect ${esc(r.citationLabel||r.title)}" title="${esc(r.id)} / worksheet row ${r.sourceRow}">${esc(r.citationLabel||r.title)}</a>${review?`<span class="reference-review">Workbook: ${r.verified?'marked verified':'not marked verified'}${r.review!=='Clean'?` / ${esc(r.review.toLowerCase())}`:''}</span>`:''}</div>`).join('')}</div>`;}
function pageIntro(title,desc,aside=''){return `<div class="page-intro ${aside?'intro-grid':''}"><div><h1>${title}</h1><p class="lede">${desc}</p></div>${aside?`<div class="intro-note">${aside}</div>`:''}</div>`;}
function sectorOptions(selected='',all='All sectors'){return `<option value="">${all}</option>`+D.sectors.map(s=>`<option value="${s.id}" ${selected===s.id?'selected':''}>${esc(s.name)}</option>`).join('');}
function selectOptions(options,selected,all){return `<option value="">${all}</option>`+options.map(o=>`<option value="${esc(o)}" ${selected===o?'selected':''}>${esc(o)}</option>`).join('');}
function showSectors(){return pageIntro('How do red lines become enforceable?','Explore six sectors: the rules they set, how they check compliance, and what AI governance can learn.')+
 `<div class="overview-meta"><span><strong>6</strong> sectors</span><span><strong>${D.records.length}</strong> verified provisions</span><a href="#lessons" class="text-link">Explore the lessons for AI <span aria-hidden="true">→</span></a></div>
 <div class="sector-grid">${D.sectors.map(s=>`<article class="sector-card" style="--sector:${s.color}"><div class="sector-top"><span class="sector-icon">${icon(s.icon)}</span><span class="sector-count">${s.count} provisions</span></div><h2><a href="#sector/${s.id}">${esc(s.name)}</a></h2><p class="desc">${esc(s.summary)}</p><div class="card-meta"><span>Explore sector</span><span aria-hidden="true">→</span></div></article>`).join('')}</div>`;}

function recordCards(rows,{featured=false}={}){return rows.map(r=>`<article class="record-card"><div class="record-card-top"><div><span class="record-id">${esc(r.id)} / worksheet row ${r.sourceRow}</span><a class="record-link" href="${esc(recordHref(r))}">${esc(r.title)}</a></div><span class="pill type">${esc(r.binding||'Binding status not recorded')}</span></div>${featured?`<p class="selection-reason"><strong>Why this example</strong>${esc(r.featureReason||'Included in the supplied mapping; no separate selection rationale recorded.')}</p>`:''}<div class="record-caption">${esc(r.citationLabel||r.pinpoint||'Source location not recorded')}</div><div class="pills">${pills(r)}</div></article>`).join('');}
function showSector(id){const s=sector(id);if(!s)return `<div class="empty"><h1>Sector not found</h1><a href="#sectors">Explore all sectors</a></div>`;const tab=state.p.get('tab')||'overview',rows=D.records.filter(r=>r.sector===id),events=D.milestones.filter(m=>m.sector===id).sort((a,b)=>a.year-b.year),lessons=D.lessons.filter(l=>l.sectors.includes(id));
 let body=`<a class="back-link" href="#sectors">All sectors</a><div class="sector-heading" style="--sector:${s.color}"><span class="sector-icon">${icon(s.icon)}</span><div><h1>${esc(s.name)}</h1><p class="lede">${esc(s.summary)}</p></div></div><div class="sector-local-stats"><span>${s.count} provisions</span><span>${s.checked} marked verified</span><span>Included in the midterm paper</span></div><nav class="sector-tabs" aria-label="Sector views">${[['overview','Overview'],['history','History'],['provisions','Provisions'],['lessons','AI lessons']].map(([k,v])=>`<a class="${tab===k?'active':''}" href="${url('sector/'+id,{tab:k==='overview'?'':k})}" ${tab===k?'aria-current="page"':''}>${v}</a>`).join('')}</nav>`;
 if(tab==='history')return body+`<p class="lens-description">Selected milestones, not an exhaustive history. Dates describe the event shown; later versions of a provision may differ.</p><div class="timeline">${timelineEvents(events)}</div>`;
 if(tab==='provisions')return body+`<div class="results-toolbar"><span><strong>${rows.length}</strong> mapped provisions</span><a class="action" href="${url('evidence',{sector:id})}">Search this sector</a></div>${recordCards(rows)}`;
 if(tab==='lessons')return body+`<div class="callout">These are analytical proposals grounded in the mapped precedents. They are not measured effects or existing AI requirements.</div><div class="lesson-grid">${lessons.map(lessonCard).join('')}</div>`;
 const featured=(s.featured||s.refs.slice(0,2)).map(byId).filter(Boolean);
 return body+`<div class="callout editorial"><strong>Potential lesson for AI</strong><p>${esc(s.takeaway)}</p></div><div class="summary-grid"><section class="panel"><h3>Where the boundary sits</h3><p>${esc(s.boundary)}</p></section><section class="panel"><h3>Who checks</h3><p>${esc(s.checking)}</p></section><section class="panel"><h3>What follows a breach</h3><p>${esc(s.response)}</p>${(s.extraSources||[]).map(x=>'<p class="check-note">'+external(x.url,x.label)+'</p>').join('')}</section></div><p class="check-note">Summaries describe selected mapped mechanisms, not every institution or rule in this sector. Open the provisions below for scope and source wording.</p><div class="two-col section"><section><div class="section-heading"><h2>Two selected examples</h2><a class="text-link" href="${url('sector/'+id,{tab:'provisions'})}">All ${rows.length} provisions</a></div>${recordCards(featured,{featured:true})}</section><section><div class="section-heading"><h2>Historical milestones</h2><a class="text-link" href="${url('sector/'+id,{tab:'history'})}">Full sector timeline</a></div><div class="panel mini-milestones">${events.slice(0,4).map(m=>`<div class="mini-event"><b>${m.year}</b><div>${external(m.sourceUrl,m.title)}<p>${esc(m.dateLabel.replace(' · ',' / '))}</p></div></div>`).join('')}</div><div class="callout"><strong>Where the analogy is limited</strong><p>${esc(s.limit)}</p></div></section></div><div class="section"><div class="section-heading"><h2>Related lessons for AI</h2><a class="text-link" href="${url('sector/'+id,{tab:'lessons'})}">View ${lessons.length} lessons</a></div><div class="lesson-grid">${lessons.slice(0,2).map(lessonCard).join('')}</div></div>`;
}
function milestoneRefs(m){return refs(m.linkedRecordUids||m.linkedRecordIds);}
function timelineEvents(items){if(!items.length)return '<div class="empty"><h2>No milestones match these filters</h2><p>Choose another sector or time period.</p><a class="action" href="#timeline">Reset timeline</a></div>';const years=[...new Set(items.map(m=>m.year))].sort((a,b)=>a-b);return years.map(y=>`<section class="timeline-year" aria-label="${y}"><div class="year">${y}</div><div class="timeline-items">${items.filter(m=>m.year===y).map(m=>{const s=sector(m.sector);return `<article class="milestone" id="${esc(m.id)}" style="--sector:${s.color}"><div class="event-top"><div><div class="event-date">${esc(m.dateLabel.replace(' · ',' / '))}</div><h3>${esc(m.title)}</h3></div><a class="pill" href="#sector/${s.id}">${esc(s.short)}</a></div><p>${esc(m.summary)}</p><div class="actions">${external(m.sourceUrl,m.sourceLabel,'source-link')}<span class="pill type">${esc(m.relationship||'Selected milestone')}</span></div>${milestoneRefs(m)}${m.caution?`<p class="event-caution"><strong>Reading note:</strong> ${esc(m.caution)}</p>`:''}</article>`;}).join('')}</div></section>`).join('');}
function timelineFiltered(){const s=state.p.get('sector'),period=state.p.get('period'),q=(state.p.get('q')||'').toLowerCase();return D.milestones.filter(m=>(!s||m.sector===s)&&(!q||`${m.title} ${m.summary} ${m.sourceLabel} ${sector(m.sector).name}`.toLowerCase().includes(q))&&(!period||period==='pre1950'&&m.year<1950||period==='1950'&&m.year>=1950&&m.year<1990||period==='1990'&&m.year>=1990&&m.year<2010||period==='2010'&&m.year>=2010));}
function showTimeline(){return pageIntro('How boundaries developed.','Trace selected agreements, revisions and changes in force across sectors. Adoption, entry into force and later amendments are different events.')+`<div class="filter-bar compact"><label class="field">Search milestones<input name="timeline-search" type="search" data-filter="q" autocomplete="off" value="${esc(state.p.get('q')||'')}" placeholder="Try consent, treaty, monitoring…"></label><label class="field">Sector<select data-filter="sector" name="sector">${sectorOptions(state.p.get('sector'))}</select></label><label class="field">Time period<select name="period" data-filter="period"><option value="">All years</option>${[['pre1950','Before 1950'],['1950','1950–1989'],['1990','1990–2009'],['2010','2010 onwards']].map(([v,l])=>`<option value="${v}" ${state.p.get('period')===v?'selected':''}>${l}</option>`).join('')}</select></label></div><div id="dynamic-results">${timelineResults()}</div>`;}
function timelineResults(){const items=timelineFiltered();return `<div class="results-toolbar"><span><strong>${items.length}</strong> of ${D.milestones.length} selected milestones</span><a href="#timeline" class="text-link">Reset filters</a></div><p class="check-note">Selected milestones linked to verified provisions. Dates distinguish adoption, entry into force and revision; this is not a complete history.</p><div class="timeline">${timelineEvents(items)}</div>`;}
function compareSelection(){const v=(state.p.get('sectors')||'01,02,07').split(',').filter(x=>sector(x));return [...new Set(v)].slice(0,3);}
function showCompare(){const selected=compareSelection();const ss=selected.map(sector);return pageIntro('Compare the mechanisms.','Look across selected precedents: what is constrained, who checks compliance, and how evidence connects to action. Select up to three sectors.')+`<div class="selection-grid" role="group" aria-label="Sectors to compare">${D.sectors.map(s=>`<label class="selection-label"><input type="checkbox" data-compare="${s.id}" ${selected.includes(s.id)?'checked':''}>${esc(s.short)}</label>`).join('')}</div><div class="results-toolbar"><span>${selected.length} of 3 sectors selected</span><button class="action" data-action="share">${icon('link')}Copy comparison link</button></div>${selected.length?`<div class="table-wrap"><table class="compare-table"><caption class="sr-only">Comparison of selected mechanisms in ${ss.map(s=>esc(s.name)).join(', ')}</caption><thead><tr><th scope="col">Selected mechanisms</th>${ss.map(s=>`<th scope="col"><a href="#sector/${s.id}">${esc(s.name)}</a><div class="record-caption">${s.count} provisions / ${s.checked} marked verified</div></th>`).join('')}</tr></thead><tbody>${[['boundary','What is constrained?'],['checking','Who checks?'],['response','What can follow?'],['takeaway','Potential AI lesson'],['limit','Limits of transfer']].map(([k,v])=>`<tr class="${k==='takeaway'?'ai-row':''}"><th scope="row">${v}</th>${ss.map(s=>`<td>${esc(s[k])}</td>`).join('')}</tr>`).join('')}<tr><th scope="row">Supporting provisions</th>${ss.map(s=>`<td>${refs(s.refs)}${(s.extraSources||[]).map(x=>'<p class="check-note">'+external(x.url,x.label)+'</p>').join('')}</td>`).join('')}</tr></tbody></table></div>`:`<div class="empty"><h2>Select sectors to begin</h2><p>Choose two or three sectors for a side-by-side comparison.</p></div>`}<div class="callout"><strong>Interpret the comparison within its scope.</strong> These are selected mechanisms within each sector. A verifier, binding rule or sanction does not by itself establish effectiveness. Differences in incentives, observability and participation matter.</div>`;}
function lessonCard(l){return `<article class="lesson-card"><div class="lesson-stage">${esc(l.stage)} / Proposed AI lesson</div><h2>${esc(l.title)}</h2><div class="lesson-block"><b>Historical mechanism — synthesis</b><p>${esc(l.history)}</p></div><div class="supporting-evidence"><span class="supporting-label">Inspect the mapped evidence</span>${refs(l.refs)}</div><div class="lesson-block ai"><b>Potential application to AI</b><p>${esc(l.ai)}</p></div><div class="lesson-block limit"><b>Essential limit</b><p>${esc(l.limit)}</p></div><div class="application-question"><b>What would need to be established?</b><p>${esc(l.applicationQuestion)}</p></div><div class="basis">${esc(l.basis)}</div></article>`;}
function showLessons(){const stage=state.p.get('stage')||'',s=state.p.get('sector')||'';const rows=D.lessons.filter(l=>(!stage||l.stage===stage)&&(!s||l.sectors.includes(s)));return pageIntro('What can transfer to AI?','Use these provisional interpretations to assess a governance proposal. Each lesson links to mapped evidence, explains a potential application and its limits, and identifies what would need to be established for AI.')+`<div class="callout"><strong>Five lenses from the midterm paper.</strong> These stages organise questions about a red line; they can overlap or recur. The mapped evidence does not support scoring each sector’s maturity or claiming that all red lines pass through the stages in order.</div><div class="tabs" aria-label="Lifecycle lens"><a href="${url('lessons',{sector:s})}" class="tab ${!stage?'active':''}" ${!stage?'aria-current="true"':''}>All lessons</a>${stages.map(t=>`<a class="tab ${stage===t?'active':''}" href="${url('lessons',{stage:t,sector:s})}" ${stage===t?'aria-current="true"':''}>${t}</a>`).join('')}</div>${stage?`<p class="lens-description">${esc(stageText[stage]||'')}</p>`:''}<div class="results-toolbar"><span><strong>${rows.length}</strong> analytical lessons</span><label class="field">Filter by precedent sector<select name="lesson-sector" data-filter="sector">${sectorOptions(s)}</select></label></div>${rows.length?`<div class="lesson-grid">${rows.map(lessonCard).join('')}</div>`:`<div class="empty"><h2>No lesson is mapped to this combination</h2><p>This does not mean there is no relevant precedent.</p><a class="action" href="#lessons">Show all lessons</a></div>`}`;}
function evidenceFiltered(){const p=state.p,q=(p.get('q')||'').trim().toLowerCase(),sec=p.get('sector'),type=p.get('type');return D.records.filter(r=>(!sec||r.sector===sec)&&(!type||r.type===type)&&(!q||[r.id,r.title,r.originalTitle,r.instrument,r.pinpoint,r.quote,r.issuer,r.transfer,r.limit,r.analogue,sector(r.sector).name].join(' ').toLowerCase().includes(q)));}
function showEvidence(){return pageIntro('Inspect the evidence.','Search the 32 verified provisions across six sectors. Open a record for its source wording, governance mechanisms and transfer notes.')+`<div class="filter-bar compact"><label class="field">Search the evidence<input name="evidence-search" type="search" data-filter="q" autocomplete="off" value="${esc(state.p.get('q')||'')}" placeholder="Try safeguards, consent, RL-01…"></label><label class="field">Sector<select name="evidence-sector" data-filter="sector">${sectorOptions(state.p.get('sector'))}</select></label><label class="field">Boundary type<select name="boundary-type" data-filter="type">${selectOptions([...new Set(D.records.map(r=>r.type))].sort(),state.p.get('type'),'All types')}</select></label></div><div id="dynamic-results">${evidenceResults()}</div><p class="check-note">Verified means the source workbook’s checkbox is set to true. Legal status is reported as recorded; blank cells mean “not recorded.” <a href="#methods">Sources & methods</a></p>`;}

function evidenceResults(){const rows=evidenceFiltered(),size=12,totalPages=Math.max(1,Math.ceil(rows.length/size)),page=Math.min(Math.max(1,Number(state.p.get('page'))||1),totalPages),view=rows.slice((page-1)*size,page*size);return `<div class="results-toolbar"><span role="status" aria-live="polite"><strong>${rows.length}</strong> of ${D.records.length} provisions</span><div class="actions"><a href="#evidence" class="action subtle">Reset filters</a><button class="action" data-action="download-csv">${icon('download')}Export results</button></div></div>${rows.length?`<div class="table-wrap"><table class="evidence-table"><thead><tr><th scope="col">Provision & source location</th><th scope="col">Sector</th><th scope="col">Boundary</th><th scope="col">Source review</th></tr></thead><tbody>${view.map(r=>`<tr><td><span class="record-id">${esc(r.id)} / worksheet row ${r.sourceRow}</span><a class="record-link" href="${esc(recordHref(r))}">${esc(r.title)}</a><div class="record-caption">${esc(r.pinpoint||'Location not recorded')}${r.flags.length?' / Data note':''}</div></td><td><a href="#sector/${r.sector}">${esc(sector(r.sector).short)}</a></td><td><span class="pill type">${esc(r.type)}</span><div class="record-caption">${esc(r.binding||'Not recorded')}</div></td><td><div class="pills"><span class="pill ${r.verified?'checked':'pending'}">${r.verified?'Marked verified':'Not marked verified'}</span>${r.review!=='Clean'?`<span class="pill query">${esc(r.review)}</span>`:''}</div></td></tr>`).join('')}</tbody></table></div><div class="pagination">${page>1?`<a class="action" href="${esc(currentUrl({page:page-1}))}">Previous</a>`:'<button class="action" disabled>Previous</button>'}<span>Page ${page} of ${totalPages}</span>${page<totalPages?`<a class="action" href="${esc(currentUrl({page:page+1}))}">Next</a>`:'<button class="action" disabled>Next</button>'}</div>`:`<div class="empty"><h2>No provisions match these filters</h2><p>Try a broader term or remove a sector or type filter.</p><a class="action" href="#evidence">Show all provisions</a></div>`}`;}
function showMethods(){return `<div class="methods">${pageIntro('Sources & methods.','The research, scope and interpretation behind this atlas.')}
 <p class="authors"><strong>Research by ${esc(D.meta.authors)}</strong></p>
 <p class="snapshot-note">Snapshot: 20 Nov 2026 · Workbook modified: 29 Oct 2026 · Static dataset, updated manually · Unit: one mapped provision or boundary.</p>
 <div class="actions">${external(D.meta.workbook,'Source workbook','action primary')}${external(D.meta.paper,'Midterm paper','action')}<button class="action" data-action="download-json">${icon('download')}Download atlas data</button></div>
 <h2>Scope</h2><p>${D.records.length} provisions across the six sectors in the midterm paper: nuclear; chemical and biological weapons; biotech and human genetics; pharmaceuticals and human research; finance and anti-money laundering; and export controls. Only rows marked “Verified” in the workbook are included. All views and downloads use this same set.</p><p>The atlas adds ${D.milestones.length} selected historical milestones linked to those provisions and ${D.lessons.length} proposed lessons for AI. This is a selected collection, not a comprehensive inventory or a measure of sector effectiveness.</p>
 <h2>Reading the evidence</h2><p>Source wording, article references and workbook notes remain inspectable in each record. Sector summaries, timelines and AI lessons are AI-assisted interpretations; separate human review of these additions is not recorded. A verified source row does not validate an AI-transfer claim.</p><p>Dates distinguish adoption, entry into force and revision. Legal status and party counts retain their source context. Changes to the Google workbook do not automatically update this snapshot.</p>
 <h2>Data notes</h2><ul><li><strong>Source IDs:</strong> RL-06-04 appears for both Nuremberg withdrawal and Helsinki consent. Unique dashboard keys and worksheet-row locators distinguish them. The non-standard Helsinki ethics-review ID, RL-06-0, is retained.</li><li><strong>IAEA threshold:</strong> the display title of RL-01-06 is corrected. Significant quantities inform safeguards detection goals; they are not possession bans. The original title remains in the record. ${external('https://www-pub.iaea.org/MTCD/publications/PDF/nvs-3-cd/PDF/NVS3_prn.pdf','IAEA Safeguards Glossary, §§3.14 and 3.23')}.</li><li><strong>Continuation cells:</strong> instrument-level fields in four explicit continuation rows are resolved from the earlier entry: RL-01-02, RL-01-03, RL-02-02 and RL-03-02. Each resolution is disclosed and original blanks are preserved.</li><li><strong>Missing information:</strong> blank fields mean “not recorded,” not that a mechanism does not exist.</li></ul>
 <h2>The lifecycle lens</h2><p>Emergence, Hardening, Detection, Consequence and Survival come from the midterm paper. They organise the lessons for AI. Stages can overlap or recur; the evidence does not justify a universal sequence, sector maturity scores or rankings.</p>
 <h2>Boundary types</h2><p>“Red line” follows the workbook’s broad usage. Some boundaries are conditional requirements rather than absolute prohibitions.</p><dl class="glossary"><div><dt>Ban</dt><dd>A specified activity is prohibited.</dd></div><div><dt>Comprehensive</dt><dd>Several activities across a capability’s lifecycle are prohibited.</dd></div><div><dt>Gate</dt><dd>An activity requires approval, evidence or another condition.</dd></div><div><dt>Threshold</dt><dd>A defined level triggers a duty, restriction or checking requirement.</dd></div><div><dt>Duty</dt><dd>A categorical obligation to act or maintain a condition.</dd></div></dl>
 <h2>Research and conceptual references</h2><p>These references appear in the midterm paper and help situate the comparison. The evidence library links each mapped provision to its own source.</p><ul class="source-list"><li>${external('https://doi.org/10.1162/002081800551271','Abbott et al. (2000), The Concept of Legalization')}<p>Obligation, precision and delegation as distinct dimensions of legalisation.</p></li><li>${external('https://doi.org/10.1162/002081800551280','Abbott & Snidal (2000), Hard and Soft Law in International Governance')}<p>A conceptual reference for comparing formally binding and non-binding instruments.</p></li><li>${external('https://doi.org/10.1017/S0020818300027910','Chayes & Chayes (1993), On Compliance')}<p>A reference for interpreting compliance mechanisms and the conditions under which they operate.</p></li><li>${external('https://doi.org/10.48550/arXiv.2507.15916','Baker et al. (2025), Verifying International Agreements on AI')}<p>An AI-specific verification reference cited in the paper; it is not a historical provision in the dataset.</p></li></ul>

 <h2>Limits of transfer</h2><p>A formal rule or institutional power does not establish enforcement in practice. Incentives, observability, participation and the nature of the technology differ across sectors. AI lessons are proposals to assess, not demonstrated causal effects or existing AI requirements.</p></div>`;}

function longValue(v){return v?esc(v):'<span class="check-note">Not recorded in the workbook.</span>';}
function openRecord(uid){const r=byUid(uid);if(!r){navigate({},['record'],true);toast('That record was not found.');return;}const s=sector(r.sector);const inherited=r.inherited.map(x=>`${x.field} from ${x.from}`).join('; ');$('#record-content').innerHTML=`<div class="dialog-top"><span class="record-id">${esc(r.id)} / worksheet row ${r.sourceRow}</span><button class="icon-button" data-action="close-record" aria-label="Close provision details">${icon('close')}</button></div><div class="dialog-body"><div class="pills">${pills(r)}</div><h2 id="record-title">${esc(r.title)}</h2><p class="instrument">${esc(r.instrument||'Instrument not recorded')}</p><div class="actions">${r.source?external(r.source,'Open source text','action primary'):''}<button class="action" data-action="share">${icon('link')}Copy record link</button><a class="action subtle" data-close-nav href="#sector/${r.sector}">${esc(s.short)}</a></div>${r.flags.length?`<div class="callout warn"><ul>${r.flags.map(f=>`<li>${esc(f)}</li>`).join('')}</ul></div>`:''}${r.featureReason?`<p class="selection-reason"><strong>Editorial reason for featuring this example</strong>${esc(r.featureReason)}</p>`:''}<h3>Wording recorded in the workbook</h3><blockquote class="quote">${longValue(r.quote)}</blockquote><div class="source-link">${esc(r.pinpoint||'Pinpoint not recorded')}${r.source?` / ${external(r.source,'View the cited document')}`:''}</div><p class="check-note">Quote reproduced from the research workbook. The checkbox records source-review status. It does not approve the dashboard’s interpretation or establish the current legal position.</p><dl class="detail-grid">${[['Boundary type',r.type],['Trigger',r.trigger],['Binding status',r.binding],['Status in the workbook',r.status],['Who is bound',r.scope],['Threshold or defining condition',r.threshold]].map(([k,v])=>`<div><dt>${k}</dt><dd>${longValue(v)}</dd></div>`).join('')}</dl><h3>How it is checked</h3><p class="long-field">${longValue(r.verifier)}</p><details><summary>Access to evidence</summary><div class="long-field">${longValue(r.access)}</div></details><h3>Consequence recorded</h3><p class="long-field">${longValue(r.consequence)}</p><details><summary>Recorded breaches and non-compliance notes</summary><div class="long-field">${longValue(r.breaches)}</div></details><div class="callout"><strong>Transfer notes are analytical claims.</strong> The following text comes from the workbook. It is separate from the quoted provision and may contain proposals or unresolved assumptions.</div><div class="labelled"><span>Closest AI analogue — source notes</span><p class="long-field">${longValue(r.analogue)}</p></div><div class="labelled"><span>What could transfer — source notes</span><p class="long-field">${longValue(r.transfer)}</p></div><div class="labelled limit"><span>What does not transfer — source notes</span><p class="long-field">${longValue(r.limit)}</p></div><details><summary>Provenance, review and original fields</summary><dl class="detail-grid"><div><dt>Source</dt><dd>${external(D.meta.workbook,'Red-Line Tracker v2.xlsx')}<br>Provision row ${r.sourceRow}</dd></div><div><dt>Verified checkbox</dt><dd>${r.verified?'True':'False'} (as recorded)</dd></div><div><dt>Coding review (CLAUDE)</dt><dd>${esc(r.review||'Not recorded')}</dd></div><div><dt>Unique dashboard key</dt><dd>${esc(r.uid)}</dd></div></dl>${inherited?`<p class="check-note"><strong>Resolved continuation fields:</strong> ${esc(inherited)}. These were blank in this source row.</p>`:''}${r.originalTitle!==r.title?`<p class="long-field"><strong>Original title:</strong> ${esc(r.originalTitle)}</p>`:''}<div class="long-field"><strong>Source notes and questions</strong><p>${longValue(r.notes)}</p></div><div class="long-field"><strong>Recorded party count (may be dated)</strong><p>${longValue(r.parties)}</p></div><p class="check-note">Worksheet locators count the original workbook’s header and instructional rows. No source cells were edited.</p></details></div>`;
 if(!dialog.open){focusBeforeDialog=document.activeElement;dialog.showModal();document.body.style.overflow='hidden';}dialog.scrollTop=0;}
function closeRecord(){if(dialog.open)dialog.close();document.body.style.overflow='';if(state.p.has('record'))navigate({},['record'],true);if(focusBeforeDialog&&focusBeforeDialog.isConnected)focusBeforeDialog.focus();}
function render(){state=readState();const route=state.route;const navRoute=route.startsWith('sector/')?'sectors':route;$('#navigation').innerHTML=navs.map(([k,i,n])=>`<a class="nav-link" href="#${k}" ${k===navRoute?'aria-current="page"':''}>${icon(i)}${n}</a>`).join('');$('#paper-link').href=D.meta.paper;$('#breadcrumb').textContent='Research dashboard / '+(route.startsWith('sector/')?(sector(route.split('/')[1])?.name||'Sector'):navs.find(n=>n[0]===route)?.[2]||'Historical precedents');const routeKey=route+'?'+[...state.p].filter(([k])=>k!=='record').map(([k,v])=>k+'='+v).join('&');if(routeKey!==previousRoute){if(dialog.open){dialog.close();document.body.style.overflow='';}main.innerHTML=route.startsWith('sector/')?showSector(route.split('/')[1]):({sectors:showSectors,timeline:showTimeline,compare:showCompare,lessons:showLessons,evidence:showEvidence,methods:showMethods}[route]||showSectors)();if(previousRoute)window.scrollTo({top:0,behavior:'instant'});previousRoute=routeKey;document.title=(route.startsWith('sector/')?sector(route.split('/')[1])?.name:navs.find(n=>n[0]===route)?.[2])+' | The Commitment Atlas';}if(state.p.has('record'))openRecord(state.p.get('record'));else if(dialog.open)closeRecord();}
function refreshResults(){if(state.route==='evidence')$('#dynamic-results').innerHTML=evidenceResults();else if(state.route==='timeline')$('#dynamic-results').innerHTML=timelineResults();else{previousRoute='';render();}previousRoute=state.route+'?'+[...state.p].filter(([k])=>k!=='record').map(([k,v])=>k+'='+v).join('&');}
function download(data,name,type){const blob=new Blob([data],{type}),href=URL.createObjectURL(blob),a=document.createElement('a');a.href=href;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(href),2000);toast('Download prepared.');}
function exportCSV(){const keys=['uid','id','sourceRow','sectorLabel','title','instrument','pinpoint','source','type','binding','status','verified','review','quote','verifier','access','consequence','analogue','transfer','limit'];const csvCell=v=>{let s=String(v??'');if(/^[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';};const rows=evidenceFiltered();download('\ufeff'+[keys,...rows.map(r=>keys.map(k=>r[k]))].map(row=>row.map(csvCell).join(',')).join('\r\n'),'commitment-atlas-filtered.csv','text/csv;charset=utf-8');}
async function share(){try{await navigator.clipboard.writeText(location.href);toast('Link copied.');}catch{toast('Copy the address from your browser to share this view.');}}
function applyTheme(theme){const dark=theme==='dark';document.documentElement.dataset.theme=dark?'dark':'light';const button=$('#theme-toggle');button.setAttribute('aria-pressed',String(dark));button.setAttribute('aria-label',dark?'Switch to day mode':'Switch to night mode');button.innerHTML=`<svg viewBox="0 0 24 24" aria-hidden="true">${dark?'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/>':'<path d="M20.5 13.5A8.5 8.5 0 0 1 10.5 3.5 8.5 8.5 0 1 0 20.5 13.5Z"/>'}</svg><span>${dark?'Day mode':'Night mode'}</span>`;const meta=$('meta[name="theme-color"]');if(meta)meta.setAttribute('content',dark?'#111923':'#ffffff');}
function toggleTheme(){const next=document.documentElement.dataset.theme==='dark'?'light':'dark';applyTheme(next);try{localStorage.setItem('commitment-atlas-theme',next);}catch{}}
applyTheme(document.documentElement.dataset.theme);
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;if(a==='toggle-theme')toggleTheme();if(a==='close-record')closeRecord();if(a==='share')share();if(a==='download-csv')exportCSV();if(a==='download-json')download(JSON.stringify(D,null,2),'commitment-atlas-data.json','application/json');});
main.addEventListener('input',e=>{const input=e.target;if(input.matches('input[type=search][data-filter]')){navigate({[input.dataset.filter]:input.value,page:null},['record'],true);refreshResults();}});
main.addEventListener('change',e=>{const t=e.target;if(t.matches('select[data-filter]')){navigate({[t.dataset.filter]:t.value,page:null},['record'],true);refreshResults();}if(t.matches('[data-compare]')){const selected=compareSelection();const next=t.checked?[...selected,t.dataset.compare]:selected.filter(x=>x!==t.dataset.compare);if(next.length>3){t.checked=false;toast('Choose up to three sectors. Deselect one to compare another.');return;}location.hash=url('compare',{sectors:next.length?next.join(','):'none'});}});
dialog.addEventListener('cancel',e=>{e.preventDefault();closeRecord();});
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeRecord();}});
window.addEventListener('hashchange',render);
render();
})();
